/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int     ret;
    boolean enableFields = false;

    ret = super();
    enableFields = true;
    
    METTelemetrySetup_ds.object(fieldNum(METTelemetrySetup, FieldName1)).enabled(enableFields);
    METTelemetrySetup_ds.object(fieldNum(METTelemetrySetup, IntegrationLabel1)).enabled(enableFields);
    
    return ret;
}

            /// <summary>
            ///
            /// </summary>
            /// <param name = "_formControl"></param>
            /// <param name = "_filterStr"></param>
            public void lookup(FormControl _formControl, str _filterStr)
            {
                SysTableLookup          SysTableLookup;
                METTableFieldLookupTmp fieldLookupTmp;
                QueryBuildDataSource    queryBuildDataSource;
                QueryBuildRange         queryBuildRange;
                str                     tableName;
                DictField               dictField;
                int                     i;

                tableName   = METTelemetrySetup.TableName;
            
                Query     query      = new Query();
                int       tmpTableid = tablename2id(tableName);
                DictTable dictTable  = new DictTable(tableName2id(tableName));

                select firstonly RecId from fieldLookupTmp where fieldLookupTmp.TablenumId == tmpTableid;

                if(!fieldLookupTmp)
                {
                    ttsBegin;
                    if (dictTable)
                    {
                        for (i=1; i<=dictTable.fieldCnt(); i++)
                        {
                            dictField = new DictField(dictTable.id(), dictTable.fieldCnt2Id(i));

                            if(subStr(dictField.name(),0,4) == "@MET:DictField")
                            {
                                continue;
                            }
                            else
                            {
                                fieldLookupTmp.field = dictField.name();
                                fieldLookupTmp.TableNumId = tmpTableid;
                                fieldLookupTmp.insert();
                            }
                        }
                    }
                    else
                    {
                        error(strFmt("@MET:ErrorStr", tableName));
                    }
                    ttsCommit;
                }
                sysTableLookup = SysTableLookup::newParameters(tableNum(METTableFieldLookupTmp), _formControl);
                sysTableLookup.addLookupField(fieldNum(METTableFieldLookupTmp, field));

                queryBuildDataSource    = query.addDataSource(tableNum(METTableFieldLookupTmp));
                queryBuildDataSource.addSortField(fieldNum(METTableFieldLookupTmp, field), SortOrder::Ascending);
                queryBuildRange         = queryBuildDataSource.addRange(fieldNum(METTableFieldLookupTmp, TablenumId));
                queryBuildRange.value(int2str(tmpTableid));

                sysTableLookup.parmQuery(query);
                sysTableLookup.performFormLookup();
            }

