            /// <summary>
            ///
            /// </summary>
            /// <param name = "_formControl"></param>
            /// <param name = "_filterStr"></param>
            public void lookup(FormControl _formControl, str _filterStr)
            {
                SysTableLookup                  sysTableLookup;
                TmpTableName                    tmpTableName;
                Query                           query;
                QueryBuildDataSource            queryBuildDataSource;
                container                       jobSpecTablesContainer;

                jobSpecTablesContainer = [tableNum(DMFDefinitionGroupExecution), tableNum(Batch)];
                for(int i = 1; i <= conLen(jobSpecTablesContainer); i++)
                {
                    tmpTableName.RefTableId = conPeek(jobSpecTablesContainer, i);
                    tmpTableName.TableName = tableId2Name(tmpTableName.RefTableId);
                    tmpTableName.insert();
                }

                sysTableLookup = SysTableLookup::newParameters(tableNum(TmpTableName), _formControl);
                sysTableLookup.addLookupField(fieldNum(TmpTableName, TableName));

                query = new Query();
                queryBuildDataSource    = query.addDataSource(tableNum(TmpTableName));

                sysTableLookup.parmQuery(query);
                sysTableLookup.parmTmpBuffer(tmpTableName);
                sysTableLookup.performFormLookup();
            }

            /// <summary>
            ///
            /// </summary>
            public void modified()
            {
                boolean enableFields = false;
                        
                enableFields = true;
            
                METTelemetrySetup_ds.object(fieldNum(METTelemetrySetup, FieldName1)).enabled(enableFields);
                METTelemetrySetup_ds.object(fieldNum(METTelemetrySetup, IntegrationLabel1)).enabled(enableFields);
                
                METTelemetrySetup.FieldName = '';
                METTelemetrySetup.IntegrationLabel = '';
                           

            }
